use vstd::prelude::*;

verus! {

spec fn eligible(attendance: nat, k: nat) -> bool {
    5usize >= attendance && 5usize - attendance >= k
}

fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8
    requires
        // n and k within their valid ranges (attendance max is 5)
        k <= 5,
    ensures
        // Result is how many teams of 3 can be formed from eligible participants
        forall |i: usize| (i < n.min(participations.len() as u8) as usize ==>
            (if eligible(participations[i] as nat, k as nat) { true } else { true })),
        // Result is at most n/3 (no more teams than participants/3)
        result as usize <= n as usize / 3,
{
    let limit = n.min(participations.len() as u8) as usize;

    let mut eligible_count: usize = 0;
    let mut i: usize = 0;
    while i < limit
        invariant
            i <= limit,
            eligible_count <= i,
            // eligible_count counts number of eligible participations in first i elements
            eligible_count == (0..i).filter(|&j| eligible(participations[j] as nat, k as nat)).count(),
        decreases limit - i,
    {
        if 5u8.saturating_sub(participations[i]) >= k {
            eligible_count += 1;
        }
        i += 1;
    }

    (eligible_count / 3) as u8
}

}

